  "ui.finalOnboarding.f9573d1164": "Tudo pronto para criar",
  "ui.finalOnboarding.45ddd1221b": "A edição no WordPress e Gutenberg é gratuita. Não exige licença nem teste.",
  "ui.finalOnboarding.6072f06060": "Ative sua licença para começar. Já ativou? Sua licença aparecerá aqui.",
